CREATE TABLE IF NOT EXISTS financial_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_type text NOT NULL, owner_id uuid NOT NULL, account_type text NOT NULL, currency char(3) NOT NULL DEFAULT 'COP', status text NOT NULL DEFAULT 'ACTIVE', UNIQUE(owner_type,owner_id,account_type,currency));
CREATE TABLE IF NOT EXISTS ledger_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transaction_type text NOT NULL, reference_type text NOT NULL, reference_id uuid, status text NOT NULL DEFAULT 'POSTED', idempotency_key text NOT NULL UNIQUE, posted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ledger_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ledger_transaction_id uuid NOT NULL REFERENCES ledger_transactions(id), financial_account_id uuid NOT NULL REFERENCES financial_accounts(id), direction text NOT NULL CHECK (direction IN ('DEBIT','CREDIT')), amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL DEFAULT 'COP');
CREATE TABLE IF NOT EXISTS topups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL DEFAULT 'MOCK', amount_minor bigint NOT NULL CHECK (amount_minor > 0), currency char(3) NOT NULL DEFAULT 'COP', status text NOT NULL DEFAULT 'POSTED', external_reference text, idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), original_payment_id uuid, amount_minor bigint NOT NULL CHECK (amount_minor > 0), reason_code text NOT NULL, status text NOT NULL DEFAULT 'POSTED', idempotency_key text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payment_webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text NOT NULL, event_type text NOT NULL, payload_json jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'PROCESSED', received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,event_id));
